<section class="container detail-hero"><div><p class="eyebrow"><?=e($row['body']['eyebrow']??t('مجالات أعمالنا','OUR FIELDS OF WORK'))?></p><h1><?=e($row['title'])?></h1><p class="large-copy"><?=e($row['summary'])?></p><a class="button" href="<?=url('contact?sector='.urlencode($type==='sectors'?$row['slug']:((array_column($sectors,'slug','id'))[$row['sector_id']]??'')))?>"><?=t('استفسر عن هذا القطاع','Enquire about this sector')?> <span class="arrow" aria-hidden="true">↗</span></a></div><?php page_slider($row,$type,$slug,'detail');?></section>
<section id="scope" class="container section scope-section"><div><p class="eyebrow"><?=t('نطاق العمل','SCOPE OF WORK')?></p><h2><?=t('تفاصيل تصنع الصورة الكاملة.','The complete picture.')?></h2></div><div class="scope-list"><?php foreach($row['body']['services']??[] as $i=>$service):?><div><span dir="ltr"><?=sprintf('%02d',$i+1)?></span><h3><?=e($service)?></h3><span aria-hidden="true">↗</span></div><?php endforeach;?><?=paragraphs($row['body']['text']??'')?></div></section>
<?php if($type==='projects'):?><section id="project-details" class="container section project-facts"><h2><?=t('بيانات المشروع','Project details')?></h2><dl><?php foreach(['location'=>t('الموقع','Location'),'scope'=>t('النطاق','Scope'),'completion_status'=>t('الحالة','Status'),'client'=>t('الجهة المستفيدة','Beneficiary')] as $k=>$label):if(!empty($row['body'][$k])):?><div><dt><?=$label?></dt><dd><?=e($row['body'][$k])?></dd></div><?php endif;endforeach;?></dl></section><div class="container project-gallery"><?php foreach(json_decode($row['gallery']??'[]',true)??[] as $id):echo picture((int)$id);endforeach;?></div><?php endif;?>
<?php foreach(sections($row) as $s):?><section class="container section about-block"><h2><?=e($s['title'])?></h2><div class="prose"><?=paragraphs($s['text'])?></div></section><?php endforeach;?>
<?php $related=$type==='sectors'?array_values(array_filter($projects,fn($p)=>(int)$p['sector_id']===(int)$row['id'])):[];if($related):?><section class="container section"><h2><?=t('أعمال ذات صلة','Related work')?></h2><?php $listedProjects=$related;require ROOT.'/app/views/project-grid.php';?></section><?php endif;?>
<section class="container section related-sectors"><div class="section-heading"><h2><?=t('اكتشف قطاعات أخرى','Explore other sectors')?></h2><a class="text-link" href="<?=url('sectors')?>"><?=t('جميع القطاعات','All sectors')?> ↗</a></div><div class="related-links"><?php foreach(array_slice(array_values(array_filter($sectors,fn($x)=>$type!=='sectors'||$x['id']!==$row['id'])),0,3) as $sector):?><a href="<?=url('sectors/'.$sector['slug'])?>"><?=e($sector['title'])?><span class="arrow" aria-hidden="true">↗</span></a><?php endforeach;?></div></section>
